(() => {
'use strict';
const D=window.MealData,E=window.MealEngine,STORE='family-table-test-v1';
const main=document.getElementById('main'),modalRoot=document.getElementById('modal-root');
const labels={breakfast:'早餐',lunch:'午餐',dinner:'晚餐',snack:'下午加餐'};
const groups={grain:'主食',protein:'鱼肉蛋豆',veg:'蔬菜',fruit:'水果',dairy:'奶类',nuts:'坚果种子',condiment:'调料与油',other:'其他食材'};
const cats={breakfast:'早餐组合',grain:'主食',protein:'蛋白质菜',veg:'蔬菜',snack:'加餐'};
const nutrients={kcal:['能量','千卡'],protein:['蛋白质','g'],carbs:['碳水化合物','g'],fat:['脂肪','g'],fiber:['膳食纤维','g'],sodium:['钠','mg'],calcium:['钙','mg'],saturatedFat:['饱和脂肪','g']};
const baseFoodIds=Object.keys(D.foods);
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const addDay=(day,n)=>{const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const monday=day=>{const d=new Date(day+'T12:00:00Z');return addDay(day,-((d.getUTCDay()+6)%7));};
const dateLabel=day=>{const d=new Date(day+'T12:00:00Z');return `${d.getUTCMonth()+1}月${d.getUTCDate()}日 ${['周日','周一','周二','周三','周四','周五','周六'][d.getUTCDay()]}`;};
const member=(id,name,extra={})=>({id,name,age:null,sex:'unknown',height:null,weight:null,stage:'adult',focus:[],specialDiet:true,profileConfirmed:false,portions:{grain:1,protein:1,veg:1,fruit:1,dairy:1,nuts:1},...extra});
function fresh(){return {version:1,catalogVersion:D.catalogVersion||1,house:'home',person:'me',planPerson:'me',day:today(),meal:'dinner',period:'week',view:'plan',filter:'all',shopRange:'week',bought:{},records:[],water:[],feedback:[],houses:{
 home:{name:'我家',city:'shanghai',plans:{},customRecipes:[],customFoods:{},members:[member('me','我',{stage:'lactating',sex:'female'}),member('partner','老公',{sex:'male'}),member('grandpa','爷爷',{stage:'elder'}),member('grandma','奶奶',{stage:'elder'}),member('child','孩子',{age:5,stage:'child',portions:{grain:.65,protein:.65,veg:.6,fruit:.7,dairy:1,nuts:.5}})]},
 care:{name:'照护家庭',city:'guangzhou',plans:{},customRecipes:[],customFoods:{},members:[member('caregiver','照护者'),member('elder1','长辈一',{stage:'care'}),member('elder2','长辈二',{stage:'care'})]},
 solo:{name:'一人食',city:'shanghai',plans:{},customRecipes:[],customFoods:{},members:[member('solo','我')]}}};}
function parseBackup(text){return JSON.parse(text,(key,value)=>{if(['__proto__','prototype','constructor'].includes(key))throw new Error('Invalid backup key');return value;});}
function validateBackup(data){
 const obj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),str=v=>typeof v==='string',num=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0;
 const id=v=>str(v)&&/^[A-Za-z0-9][A-Za-z0-9_-]{0,100}$/.test(v),date=v=>str(v)&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
 const strings=v=>Array.isArray(v)&&v.every(str),need=value=>{if(!value)throw new Error('Invalid backup structure');},spaces=['home','care','solo'];
 need(obj(data)&&data.version===1&&obj(data.houses)&&Object.keys(data.houses).length===3&&spaces.every(k=>obj(data.houses[k])));
 need(spaces.includes(data.house)&&date(data.day)&&Object.hasOwn(labels,data.meal)&&['day','week'].includes(data.period)&&['plan','shop','library','me'].includes(data.view)&&['day','week'].includes(data.shopRange)&&['all','prep','season','book',...Object.keys(cats)].includes(data.filter));
 for(const key of spaces){
  const space=data.houses[key];need(str(space.name)&&['shanghai','guangzhou'].includes(space.city)&&Array.isArray(space.members)&&space.members.length>0&&obj(space.plans)&&Array.isArray(space.customRecipes)&&obj(space.customFoods));
  const members=new Set();for(const p of space.members){need(obj(p)&&id(p.id)&&!members.has(p.id)&&str(p.name)&&p.name.trim()&&obj(p.portions)&&Object.values(p.portions).every(num)&&strings(p.focus)&&typeof p.specialDiet==='boolean'&&typeof p.profileConfirmed==='boolean'&&['unknown','male','female'].includes(p.sex)&&['adult','child','elder','care','lactating'].includes(p.stage));for(const v of [p.age,p.height,p.weight])need(v===null||num(v));if(p.notes!==undefined)need(str(p.notes));for(const key of ["foodLikes","foodDislikes","priorityRecipes","temporaryAvoid"]){if(p[key]!==undefined)need(strings(p[key])&&p[key].length<=1000);}if(p.recipeRatings!==undefined)need(obj(p.recipeRatings)&&Object.entries(p.recipeRatings).every(([k,v])=>id(k)&&Number.isInteger(v)&&v>=1&&v<=5));if(p.customGoals!==undefined)need(obj(p.customGoals)&&Object.values(p.customGoals).every(g=>obj(g)&&["minimum","maximum","range"].includes(g.type)&&[g.min,g.max].every(v=>v===undefined||v===null||num(v))));if(p.portionOverrides!==undefined)need(obj(p.portionOverrides)&&Object.values(p.portionOverrides).every(v=>num(v)&&v>0&&v<=3));members.add(p.id);}
  const foodIds=new Set(baseFoodIds),recipeIds=new Set(D.recipes.concat(D.retiredRecipes||[]).map(r=>r.id));
  for(const [key,f] of Object.entries(space.customFoods)){need(id(key)&&key.startsWith('custom-')&&!baseFoodIds.includes(key)&&obj(f)&&f.id===key&&str(f.name)&&['g','mL'].includes(f.unit)&&Object.hasOwn(groups,f.group)&&obj(f.nutrients)&&typeof f.verified==='boolean'&&obj(f.source));if(!Object.hasOwn(f.nutrients,'saturatedFat'))f.nutrients.saturatedFat=null;for(const n of Object.keys(nutrients))need(Object.hasOwn(f.nutrients,n)&&(f.nutrients[n]===null||num(f.nutrients[n])));for(const field of ['label','url','id','state'])need(str(f.source[field]));need(!f.source.url||/^https?:\/\//.test(f.source.url));foodIds.add(key);}
  if(space.pantry!==undefined){need(Array.isArray(space.pantry)&&space.pantry.length<=1000);for(const row of space.pantry)need(obj(row)&&id(row.id)&&str(row.name)&&Object.hasOwn(groups,row.group)&&foodIds.has(row.foodId)&&["available","out"].includes(row.status)&&str(row.note));}
  for(const r of space.customRecipes){need(obj(r)&&id(r.id)&&r.id.startsWith('recipe-')&&!recipeIds.has(r.id)&&str(r.name)&&Object.hasOwn(cats,r.category)&&Array.isArray(r.ingredients)&&(r.ingredients.length>0||r.incomplete===true)&&num(r.portions)&&r.portions>0&&(r.cookedG===null||num(r.cookedG)&&r.cookedG>0)&&num(r.activeMin)&&num(r.totalMin)&&r.totalMin>=r.activeMin&&strings(r.steps)&&r.steps.length>0&&strings(r.tags)&&obj(r.prep)&&['fresh','raw-frozen','blanched-frozen','cooked-frozen'].includes(r.prep.mode));for(const i of r.ingredients)need(obj(i)&&foodIds.has(i.foodId)&&num(i.g)&&i.g>0);recipeIds.add(r.id);}
  for(const [key,m] of Object.entries(space.plans)){const match=key.match(/^(\d{4}-\d{2}-\d{2})-(breakfast|lunch|dinner|snack)$/);need(match&&date(match[1])&&obj(m)&&strings(m.recipeIds)&&m.recipeIds.every(r=>recipeIds.has(r))&&strings(m.people)&&new Set(m.people).size===m.people.length&&m.people.every(p=>members.has(p))&&obj(m.dishPeople)&&obj(m.size));for(const [r,list] of Object.entries(m.dishPeople))need(recipeIds.has(r)&&strings(list)&&list.every(p=>members.has(p)));for(const [p,size] of Object.entries(m.size))need(members.has(p)&&num(size)&&size>0);}
 }
 const selected=data.houses[data.house].members;need(selected.some(p=>p.id===data.person)&&selected.some(p=>p.id===data.planPerson));
 need(Array.isArray(data.records)&&Array.isArray(data.water)&&Array.isArray(data.feedback)&&obj(data.bought)&&Object.values(data.bought).every(num));
 const owner=r=>obj(r)&&spaces.includes(r.house)&&data.houses[r.house].members.some(p=>p.id===r.owner)&&date(r.day);
 for(const r of data.records){need(owner(r)&&str(r.id)&&str(r.text)&&Object.hasOwn(labels,r.period));if(r.actor!==undefined)need(data.houses[r.house].members.some(p=>p.id===r.actor));for(const field of ['portionText','note'])if(r[field]!==undefined)need(str(r[field]));need(r.kcal===null||Array.isArray(r.kcal)&&r.kcal.length===2&&r.kcal.every(num)&&r.kcal[0]<=r.kcal[1]);}
 for(const r of data.water)need(owner(r));for(const r of data.feedback)need(obj(r)&&str(r.text)&&str(r.time)&&!Number.isNaN(Date.parse(r.time)));
 return data;
}
function loadStoredState(){
 let raw=null;try{raw=localStorage.getItem(STORE);return raw===null?fresh():validateBackup(parseBackup(raw));}
 catch{if(typeof raw==='string'){try{let key=STORE+':recovery:'+Date.now();while(localStorage.getItem(key)!==null)key+='-1';localStorage.setItem(key,raw);}catch{return null;}setTimeout(()=>notify('旧资料格式无法读取，已保留恢复副本，本次使用空白记录。'),0);}return fresh();}
}
let s=loadStoredState();if(s===null){main.textContent='旧资料未能建立恢复副本，本次停止载入，原数据保持不变。';return;}
let modal=null,chooseQuery='',chooseFilter='protein',changeIndex=null,toastTimer=null,skillFilter='',bookSearch='',bookCategory='all',bookLimit=30,bookPage=0,recipePage=0,recipeQuery='',sheetTrigger=null,sheetScroll=0,sheetBodyStyle='';
const roughDrafts=Object.create(null);
const house=()=>s.houses[s.house];
const people=()=>house().members;
const findPerson=id=>people().find(p=>p.id===id)||people()[0];
const current=()=>findPerson(s.person);
const plannedPerson=()=>findPerson(s.planPerson);
const food=id=>D.foods[id]||house().customFoods[id];
const recipes=()=>D.recipes.concat(house().customRecipes.filter(r=>!r.retired));
const recipe=id=>{const active=recipes().find(r=>r.id===id);if(active)return {...active,...(D.cookingGuides?.[id]||{})};const retired=(D.retiredRecipes||[]).concat(house().customRecipes.filter(r=>r.retired)).find(r=>r.id===id);return retired?{...retired,retired:true}:undefined;};
function syncCustomFoods(){for(const space of Object.values(s.houses))Object.assign(D.foods,space.customFoods);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(s));}catch{notify('本机存储空间不足，请先导出备份。');}}
function notify(text){document.getElementById('toast-root').innerHTML=`<div class="toast" role="status">${h(text)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast-root').replaceChildren(),4200);}
const btn=(text,attrs='',cls='')=>`<button type="button" class="${cls}" ${attrs}>${text}</button>`;
const fmt=(value,key)=>value===null||!Number.isFinite(value)?'待补数据':(key==='kcal'||key==='sodium'||key==='calcium'?Math.round(value):Math.round(value*10)/10)+nutrients[key][1];
const nutText=(result,key)=>result.coverage[key]===0||result.values[key]===null?'数据未齐':(result.coverage[key]<1?'已知部分 ':'约')+fmt(result.values[key],key);
const modeName=mode=>({'raw-frozen':'原料生冻','blanched-frozen':'焯水后冷冻','cooked-frozen':'熟后冷冻',fresh:'现做 / 冷藏短备'}[mode]||'现做');
const planner=window.MealPlanning;
const pantryUI=window.PantryUI.create({getHouse:house,getFoods:()=>D.foods,save,notify,render,showSheet,closeSheet});
const preferenceUI=window.PreferenceUI.create({getHouse:house,getRecipes:recipes,getMembers:people,getPerson:plannedPerson,save,notify,render,showSheet,closeSheet});
function pick(category,index=0){const choices=D.recipes.filter(r=>r.category===category&&r.defaultEligible!==false&&!r.id.includes('out'));return choices[index%choices.length]?.id;}
function newMeal(meal,offset=0,day=s.day){return planner.build(meal,offset,{houseId:s.house,members:people(),recipes:recipes(),city:house().city,startDay:monday(day)});}
function getMeal(day=s.day,meal=s.meal){const key=day+'-'+meal;if(!house().plans[key]){const offset=(new Date(day+'T12:00:00Z').getUTCDay()+6)%7;house().plans[key]=newMeal(meal,offset,day);}return house().plans[key];}
function recipePeople(m,id){return (m.dishPeople[id]||m.people).filter(p=>m.people.includes(p));}
function mealBundle(m,id){const kind=Object.keys(house().plans).find(key=>house().plans[key]===m)?.slice(11)||s.meal;return E.mealPortions(m.recipeIds.filter(rid=>recipe(rid)&&recipePeople(m,rid).includes(id)).map(recipe),findPerson(id),kind,m.size[id]||1);}
function itemsFor(m,id){return mealBundle(m,id).items;}
function dayItems(id=s.planPerson,day=s.day){return E.mergeItems(Object.keys(labels).map(meal=>itemsFor(getMeal(day,meal),id)));}
function mealScore(m,id=s.planPerson,meal=s.meal){const items=itemsFor(m,id);return items.length?E.score(items,meal):{score:null,checks:[],note:'本餐未安排此人。'};}
function scoreLabel(score){return score===null?'未评分':score+'分';}
function personSelect(id,value=s.planPerson){return `<select class="select" id="${id}" aria-label="选择查看的成员">${people().map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${h(p.name)}</option>`).join('')}</select>`;}
function groupChip(p,selected,attribute){return btn((selected?'✓ ':'')+h(p.name),`${attribute}="${p.id}" aria-pressed="${selected}"`,'chip '+(selected?'selected':''));}
function mealTabs(){return `<div class="tabs" role="group" aria-label="餐次">${Object.entries(labels).map(([key,name])=>btn(name,`data-meal="${key}"`,s.meal===key?'active':'')).join('')}</div>`;}
function topDate(){return `<div class="date-toolbar"><div><div class="tiny">${house().city==='guangzhou'?'广州':'上海'} · ${h(house().name)}</div><h1>${s.period==='week'?'一周安排':dateLabel(s.day)}</h1></div><div class="date-actions"><input class="input" type="date" id="day-picker" value="${s.day}" aria-label="选择日期"><div class="tabs period-tabs">${btn('每日','data-period="day"',s.period==='day'?'active':'')}${btn('一周','data-period="week"',s.period==='week'?'active':'')}</div></div></div>`;}
function healthPlanPanel(){
 const rules=planner.healthGuidance(people());
 return rules.length?`<details class="notice health-rules"><summary>本周采用的健康规则 · 先适合，再看喜好</summary>${rules.map(t=>`<p class="tiny">${h(t)}</p>`).join('')}<p class="tiny">关注项用于保守排餐。急性痛风、肾功能问题、吞咽或其他饮食医嘱需按已有方案单独设置。</p></details>`:'';
}
function healthReview(m,p){
 const selected=m.recipeIds.filter(id=>recipePeople(m,id).includes(p.id)).map(recipe).filter(Boolean),notes=[],focus=p.focus||[];
 if(focus.includes('uric')){
  if(selected.some(r=>/鱿鱼|鳝|蛤|扇贝|蛏|内脏|浓肉汤|肉汁/.test(r.name)))notes.push('尿酸关注：这餐有不作为本人自动推荐的水产/浓肉汁类，可在“这道谁吃”取消本人，或换成蛋、奶、豆制品。');
  let fishMeals=0;const start=monday(s.day);
  for(let i=0;i<7;i++)for(const type of Object.keys(labels)){const plan=house().plans[addDay(start,i)+'-'+type];if(plan&&plan.recipeIds.some(id=>recipePeople(plan,id).includes(p.id)&&recipe(id)&&planner.referenceAmounts(recipe(id)).fishG>0))fishMeals++;}
  if(fishMeals>2)notes.push(`本周本人已排${fishMeals}餐水产，高于本产品尿酸关注的保守排餐次数；建议减少，具体频次需结合个人情况。`);
 }
 if(focus.includes('lipids')&&selected.some(r=>/响油|肥肉|油炸/.test(r.name)))notes.push('血脂关注：这餐有用油较多的菜，可少取油汁或换少油煎、蒸、炖菜。');
 if(focus.includes('pressure')&&E.nutrition(itemsFor(m,p.id)).coverage.sodium<1)notes.push('血压关注：本餐存在未匹配的钠数据，尤其酱汁和预制品需看标签，目前不能判断控盐已到位。');
 return notes.length?`<section class="notice health-review"><strong>${h(p.name)} · 本餐健康核对</strong>${notes.map(t=>`<p class="tiny">${h(t)}</p>`).join('')}</section>`:'';
}

function planning(){return `${topDate()}${healthPlanPanel()}<section class="notice profile-banner"><div class="row"><div><strong>先定一周，再按人分餐</strong><p class="tiny">午餐优先分装冷冻，晚餐爷爷现做。${people().filter(p=>E.profileAssessment(p).ready).length}/${people().length}位成员已有份量依据。</p></div>${btn('家人资料','data-open-profiles','small')}</div></section>${s.period==='week'?weekPage():dayPage()}`;}
function planningSummary(){const p=plannedPerson(),a=E.profileAssessment(p),n=E.nutrition(dayItems(p.id)),m=getMeal(),score=mealScore(m);const scores=['breakfast','lunch','dinner'].map(key=>mealScore(getMeal(s.day,key),p.id,key)).filter(x=>x.score!==null);const avg=scores.length===3?Math.round(scores.reduce((a,x)=>a+x.score,0)/3):null;return `<section class="soft-panel stack"><div class="row"><div><div class="tiny">看谁的计划营养</div><h2>${h(p.name)}的今天</h2></div>${personSelect('plan-person')}</div><div class="grid2"><div><div class="subtle">${labels[s.meal]}搭配完整度</div><strong class="score-value">${scoreLabel(score.score)}</strong>${btn('看依据','data-score','ghost small')}</div><div><div class="subtle">全天搭配完整度</div><strong class="score-value">${avg===null?`${scores.length}/3餐已安排`:avg+'分'}</strong></div></div><p class="tiny">按主食、蛋白、蔬果、多样性检查；是否够量要看下方个人目标。</p><p>${a.ready?`份量依据：约${Math.round(a.energyKcal)}千卡/日${a.energyKcal?'（维持需要粗估）':''}`:'份量尚未定制：'+h(a.reason)}</p><div class="row"><span>全天计划：${nutText(n,'kcal')} · 蛋白质${nutText(n,'protein')}</span>${btn('够不够 / 营养明细','data-nutrition','ghost')}</div>${btn('修改'+h(p.name)+'的资料',`data-edit-person="${p.id}"`,'ghost small')}</section>`;}
function mealCard(r,index,m){return `<article class="meal-card"><div><h3 class="meal-title">${h(r.name)}</h3><div class="meal-meta">动手${r.activeMin}分钟 · ${modeName(r.prep.mode)}</div></div>${r.uricAcidNote?'<span class="tiny">尿酸关注 · 手动选择</span>':''}<div class="meal-actions">${btn('换菜',`data-change="${index}"`,'small')}${btn('做法',`data-recipe="${r.id}"`,'ghost small')}<details class="dish-more"><summary>更多</summary><div class="wrap">${btn('这道谁吃',`data-dish-people="${r.id}"`,'small')}${btn('不做这道',`data-remove-dish="${index}"`,'ghost small')}</div></details></div></article>`;}
function portionsPanel(m){return `<section class="panel stack portion-panel"><div class="row"><h2>每人分多少</h2><span class="tiny">${m.people.length}人 · 点开看原料</span></div>${m.people.map(id=>{const p=findPerson(id),items=itemsFor(m,id).filter(i=>food(i.foodId).group!=='condiment'),totals={};for(const i of items){const f=food(i.foodId),key=f.group+'|'+f.unit;totals[key]=(totals[key]||0)+i.g;}const glance=Object.entries(totals).map(([key,g])=>{const [group,unit]=key.split('|');return `${groups[group]}${Math.round(g)}${unit}`;}).join(' · ');return `<details class="person-portion" data-portion-person="${id}"><summary><strong>${h(p.name)}<small class="tiny">${E.profileAssessment(p).ready?' · 已按资料调整':' · 待定制'}</small></strong><span class="portion-glance">${h(glance||'本餐未选菜')}</span><span class="portion-expand" aria-hidden="true">展开</span></summary><div class="portion-details">${items.map(i=>`<div class="portion-item"><span>${h(food(i.foodId).name)}</span><strong>${Math.round(i.g)}${food(i.foodId).unit}</strong></div>`).join('')}<p class="tiny">${h(mealBundle(m,id).calibrationNote)}</p><label class="portion-adjust field">这顿份量<select class="select" data-size="${id}" aria-label="${h(p.name)}这顿份量">${[[.75,'少一点'],[1,'参考份'],[1.25,'多一点']].map(([v,t])=>`<option value="${v}" ${(m.size[id]||1)===v?'selected':''}>${t}</option>`).join('')}</select></label>${p.stage==='care'?'<p class="tiny">照护份量先按已有吞咽与饮食方案核对。</p>':''}</div></details>`;}).join('')||'<p class="empty">先勾选这顿谁吃。</p>'}${btn('看厨房总量','data-prep-total','primary')}<p class="tiny">参考份按个人资料调整，整天仍需核对营养合计。以上是食物用量：米面干重，肉鱼虾及蔬菜为可食生重；并非营养素克数。</p></section>`;}
function dayPage(){const m=getMeal(),score=mealScore(m);return `<div class="plan-layout" data-plan-key="${s.house}|${s.day}|${s.meal}"><div class="plan-workspace stack"><section class="plan-controls panel stack">${mealTabs()}${m.prepNote?`<p class="tiny meal-prep-note">${h(m.prepNote)}</p>`:''}<div class="row diner-heading"><h2>这顿谁吃？</h2><div class="wrap">${btn('只我','data-only','ghost small')}${btn('全家','data-all','ghost small')}</div></div><div class="wrap diner-chips">${people().map(p=>groupChip(p,m.people.includes(p.id),'data-person')).join('')}</div></section><section class="plan-menu stack"><div class="section-heading row"><div><h2>${labels[s.meal]}吃这些</h2><p class="tiny">${h(plannedPerson().name)}的本餐搭配：${scoreLabel(score.score)} ${btn('看依据','data-score','ghost small')}</p></div>${btn('加一道','data-choose','primary')}</div>${m.recipeIds.some(id=>recipe(id)?.incomplete)?'<p class="notice tiny">这顿有只记了菜名的自家菜；这些菜尚未计入营养和采购。</p>':''}${healthReview(m,plannedPerson())}<div class="meal-grid">${m.recipeIds.map((id,i)=>recipe(id)?mealCard(recipe(id),i,m):'').join('')||'<div class="empty">先从菜谱加一道，或自己选食材。</div>'}</div><div class="menu-actions">${btn('添加自家菜','data-build','ghost')}</div></section><section class="panel prep-banner"><div class="row"><div><h3>一次分装，平日少切菜</h3><p class="tiny">主食、蛋白、蔬菜换着组合</p></div>${btn('看备餐包','data-open-prep','ghost small')}</div></section>${roughSection()}<p class="tiny privacy-note">电脑 / 手机通用测试版 · 数据仅保存在当前浏览器。换设备可在“我的”中导出和恢复备份；暂不自动同步。</p></div><aside class="plan-sidebar stack">${portionsPanel(m)}${planningSummary().replace('soft-panel stack','soft-panel stack nutrition-summary').replace('data-score','data-summary-score')}</aside></div>`;}
function weekPage(){const start=monday(s.day);return `<div class="stack"><section class="soft-panel stack week-overview"><div class="row"><div><h2>一周安排，午晚各有侧重</h2><p class="tiny">按本餐就餐人喜好、优先顺序与备餐条件生成；不会只按喜欢就无限增加肉类。</p></div>${btn('按喜好重新规划','data-replan-week','primary')}</div><div class="wrap">${btn('本周营养预估','data-week-nutrition')}${btn('本周备菜汇总','data-batch-summary','ghost')}${personSelect('plan-person')}</div><p class="tiny">${h(plannedPerson().name)}：${E.profileAssessment(plannedPerson()).ready?'已有个人份量依据':'基础资料待完善，先看参考食物用量'}；点餐次可自由替换。</p></section><div class="week-grid">${Array.from({length:7},(_,i)=>{const d=addDay(start,i);return `<section class="panel day-card"><div class="row"><h2>${dateLabel(d)}</h2>${btn('看这天',`data-day="${d}"`,'ghost small')}</div>${Object.entries(labels).map(([key,name])=>{const m=getMeal(d,key),sc=mealScore(m,s.planPerson,key);return `<div class="week-meal-row"><span>${name}${key==='lunch'?'<small class="tiny">备餐</small>':key==='dinner'?'<small class="tiny">现做</small>':''}</span><div><p>${m.recipeIds.map(id=>h(recipe(id)?.name||'')).join('、')||'待选'}</p><span class="tiny">${sc.score===null?(key==='snack'?'加餐':'未安排此人'):sc.score+'分'} · ${m.people.map(id=>h(findPerson(id).name)).join('、')||'待选人'}</span></div>${btn('调整',`data-open-meal="${d}" data-meal-type="${key}" aria-label="调整${d}${name}"`,'ghost small')}</div>`;}).join('')}</section>`;}).join('')}</div></div>`;}
function roughSection(){const rows=s.records.filter(x=>x.house===s.house&&x.owner===s.person&&x.day===s.day);return `<section class="panel stack rough-panel"><div class="row"><h2>${h(current().name)} · 实吃随手记</h2>${personSelect('record-person',s.person)}</div><p class="subtle">大概记一下即可，计划餐的营养分析看上方。</p><textarea class="input" id="rough-text" data-draft-key="${h(s.house+'|'+s.person+'|'+s.day)}" placeholder="例如：早上吃了手掌大小的酸奶碗；下午一个苹果">${h(roughDrafts[s.house+'|'+s.person+'|'+s.day]||'')}</textarea><div class="wrap">${btn('记下','data-rough-save','primary')}${btn('这顿照计划吃了','data-log-plan')}${btn('喝了一杯水','data-water-add')}</div>${rows.map(x=>`<div class="check-row"><div><strong>${h(x.text)}</strong><p class="tiny">${labels[x.period]||'随手记'} · ${h(x.portionText||'原话保留')} ${x.kcal?'· 粗估'+Math.round(x.kcal[0])+'—'+Math.round(x.kcal[1])+'千卡':''}</p></div>${btn('删除',`data-record-remove="${x.id}"`,'ghost small')}</div>`).join('')}<p class="tiny">今天记了${rows.length}笔实吃、${s.water.filter(x=>x.house===s.house&&x.owner===s.person&&x.day===s.day).length}杯水。粗记不用于精确判定营养缺乏或超量，也不会改采购。</p></section>`;}
function allShopping(){const list=[],days=s.shopRange==='week'?Array.from({length:7},(_,i)=>addDay(monday(s.day),i)):[s.day];for(const day of days)for(const meal of Object.keys(labels)){const m=getMeal(day,meal);for(const id of m.people)list.push(itemsFor(m,id));}return E.mergeItems(list).filter(i=>food(i.foodId).group!=='condiment');}
function shopping(){if(s.shopTab==='pantry')return `<div class="stack"><h1>常备食材</h1>${shopTabs()}${pantryUI.panel()}</div>`;const items=allShopping(),keyBase=s.house+'-'+s.shopRange+'-'+(s.shopRange==='week'?monday(s.day):s.day);return `<div class="stack"><div class="page-head"><div><div class="tiny">${house().name}</div><h1>照着买就好</h1></div>${btn('复制清单','data-copy-shop')}</div>${shopTabs()}<div class="tabs">${btn('选中这天','data-shop-range="day"',s.shopRange==='day'?'active':'')}${btn('这一周','data-shop-range="week"',s.shopRange==='week'?'active':'')}</div><p class="tiny">计划净用量，米面干重、肉菜可食生重；包装和带骨带壳重量需另折算。</p>${Object.entries(groups).filter(([g])=>g!=='condiment').map(([g,label])=>{const selected=items.filter(i=>food(i.foodId).group===g);return selected.length?`<section class="panel"><h2>${label}</h2>${selected.map(i=>{const key=keyBase+'-'+i.foodId,bought=Number(s.bought[key]||0)>=i.g;return `<div class="check-row"><label class="row"><input type="checkbox" data-buy="${key}" data-grams="${i.g}" ${bought?'checked':''}><span>${h(food(i.foodId).name)}<br><span class="tiny">${Math.ceil(i.g)}${food(i.foodId).unit}${!bought&&s.bought[key]?' · 用量增加，需补买':''}</span></span></label>${btn('家里有',`data-have="${key}" data-grams="${i.g}"`,'ghost small')}</div>`;}).join('')}</section>`:'';}).join('')||'<div class="empty">先安排几顿饭，再来买菜。</div>'}</div>`;}
function shopTabs(){return `<div class="tabs">${btn('采购清单','data-shop-tab="list"',s.shopTab!=='pantry'?'active':'')}${btn('家里常备','data-shop-tab="pantry"',s.shopTab==='pantry'?'active':'')}</div>`;}
function standardItems(r){return E.portion(r,{portions:{}},1);}
function recipeSkill(id){const prefs=house().recipeSkills;return prefs&&typeof prefs==='object'&&['familiar','try'].includes(prefs[id])?prefs[id]:'';}
function skillLabel(id){return recipeSkill(id)==='familiar'?'我会做':recipeSkill(id)==='try'?'想尝试':'';}
function applyCatalogRevision(){
 const version=D.catalogVersion||1;if((s.catalogVersion||1)>=version)return false;
 let changed=0;const mapping=D.recipeReplacements||{},cutoff=today();
 for(const space of Object.values(s.houses))for(const [key,m] of Object.entries(space.plans)){
  if(key.slice(0,10)<cutoff)continue;
  const next=[];
  for(const old of m.recipeIds){
   if(!Object.hasOwn(mapping,old)){next.push(old);continue;}
   const replacement=mapping[old];changed++;
   if(replacement){next.push(replacement);if(m.dishPeople[old]&&!Object.hasOwn(m.dishPeople,replacement))m.dishPeople[replacement]=m.dishPeople[old];}
   delete m.dishPeople[old];
  }
  m.recipeIds=[...new Set(next)];
 }
 s.catalogVersion=version;
 if(changed)setTimeout(()=>notify('菜谱已更新：未来计划中的旧菜已按反馈调整；实吃记录和过去餐单保留。'),0);
 return changed>0;
}
function recipeNotes(r){return [...new Set([...(Array.isArray(r.healthNotes)?r.healthNotes:[]),r.safetyNote||r.uricAcidNote].filter(Boolean))].join('；');}
function recipeTags(r){return `<div class="wrap">${skillLabel(r.id)?`<span class="badge">${skillLabel(r.id)}</span>`:''}${r.noviceTips?.length||r.guideVersion?'<span class="badge">新手步骤</span>':''}${r.adapted?'<span class="badge">家庭改写</span>':r.sourcePages?.length?'<span class="badge">书页配方</span>':''}${r.defaultEligible===false?'<span class="badge">手动可选</span>':''}</div>`;}
function matchingLibraryRecipes(){const rows=recipes().filter(r=>s.filter==='all'||r.category===s.filter).filter(r=>!skillFilter||recipeSkill(r.id)===skillFilter).filter(r=>!recipeQuery||r.name.includes(recipeQuery)||r.ingredients.some(i=>food(i.foodId)?.name.includes(recipeQuery)));return s.librarySort==='original'?rows:planner.rankRecipes(rows,[plannedPerson()]);}
function libraryRecipeResults(){const rows=matchingLibraryRecipes(),pages=Math.max(1,Math.ceil(rows.length/12));recipePage=Math.min(recipePage,pages-1);return `<div class="results-heading row"><span class="tiny">${rows.length}道菜 · 第${recipePage+1}/${pages}页</span></div><div class="recipe-grid">${rows.slice(recipePage*12,recipePage*12+12).map(r=>`<article class="panel recipe-card stack"><div><h2>${h(r.name)}</h2><p class="tiny">动手${r.activeMin}分钟 · ${modeName(r.prep.mode)}</p></div>${recipeTags(r)}${r.uricAcidNote?'<p class="tiny">尿酸关注 · 手动选择</p>':''}${preferenceUI.controls(r)}${btn('看做法',`data-recipe="${r.id}"`,'small')}</article>`).join('')||'<p class="empty">没有找到，换个关键词或筛选试试。</p>'}</div><div class="pagination">${btn('上一页',`data-recipe-page="prev" ${recipePage===0?'disabled':''}`)}<span class="page-count">${recipePage+1} / ${pages}</span>${btn('下一页',`data-recipe-page="next" ${recipePage>=pages-1?'disabled':''}`)}</div>`;}
function refreshRecipeResults(){const node=document.getElementById('recipe-results');if(node)node.innerHTML=libraryRecipeResults();}
function scrollCatalogResults(){const toolbar=document.querySelector('.library-toolbar');toolbar?.scrollIntoView({block:'start',behavior:'instant'});}
function library(){const seasonal=D.seasonal[house().city],tabs=[['all','全部菜谱'],...Object.entries(cats),['prep','冷冻备餐'],['season','当地食材']];let body='';
 if(s.filter==='prep')body=`<section class="soft-panel row"><div><h2>一次分装，几顿换着做</h2><p class="tiny">按生冻、焯冻、熟后冻分别操作。</p></div>${btn('本周备菜汇总','data-batch-summary')}</section><div class="recipe-grid">${D.prepPacks.map(p=>`<section class="panel stack"><div class="row"><h2>${h(p.name)}</h2><span class="badge">${modeName(p.freezeType)}</span></div><p>${h(p.method)}</p><p class="tiny">${h(p.portionNote)}</p><p class="tiny">搭配：${p.useFor.map(h).join('、')}</p>${btn('用到选中这顿',`data-pack-use="${p.recipeId}"`)}</section>`).join('')}</div>`;
 else if(s.filter==='season')body=`<section class="soft-panel"><h2>${house().city==='guangzhou'?'广州':'上海'}秋冬采购候选</h2><p>${seasonal.autumnWinter.map(id=>h(food(id)?.name||id)).join('、')}</p><p class="tiny">${h(seasonal.note)}</p></section><section class="panel"><h2>冷冻常备另算</h2><p>秋葵、西兰花、彩椒、洋葱可作为备餐组件，按当地供应采购。</p></section>`;

 else body=`<div class="row wrap"><label class="tiny">按谁的喜好 ${personSelect('library-person')}</label><select class="select" id="library-sort" aria-label="菜谱排序"><option value="preference" ${s.librarySort!=='original'?'selected':''}>个人喜好与优先顺序</option><option value="original" ${s.librarySort==='original'?'selected':''}>原有顺序</option></select>${btn('调整喜好顺序','data-preference-panel','ghost small')}</div><div class="library-search"><input class="input" id="recipe-search" value="${h(recipeQuery)}" aria-label="搜索菜名或食材" placeholder="搜菜名或食材，例如：三文鱼、鸡蛋"><select class="select" id="skill-filter" aria-label="按会不会做筛选"><option value="">全部做法</option><option value="familiar" ${skillFilter==='familiar'?'selected':''}>我会做</option><option value="try" ${skillFilter==='try'?'selected':''}>想尝试</option></select></div><div id="recipe-results">${libraryRecipeResults()}</div>`;
 return `<div class="stack library-page"><div class="page-head"><div><div class="tiny">${house().city==='guangzhou'?'广州':'上海'} · 简单选菜，按人分量</div><h1>备餐与菜谱</h1></div>${btn('添加自家菜','data-build')}</div><div class="library-toolbar"><div class="category-strip" role="group" aria-label="菜谱类别">${tabs.map(([key,text])=>btn(text,`data-filter="${key}" aria-pressed="${s.filter===key}"`,'chip '+(s.filter===key?'selected':''))).join('')}</div></div>${body}</div>`;}
function bookReferencePage(){const ready=(D.bookReferences||[]).filter(ref=>ref.recipeId&&recipe(ref.recipeId)).length;return `<details class="book-intro"><summary>${ready}条可直接选做 · 按菜名或食材找</summary><p class="tiny">书中有完整配方的保留原始数量；其余按检索资料整理成家庭参考配方，详情中可看改写说明与来源。用量用于备料和估算，按个人情况调整。</p></details><div class="library-search"><input class="input" id="book-search" value="${h(bookSearch)}" aria-label="搜索书页菜名" placeholder="搜索菜名，例如：瘦牛肉沙拉"><select class="select" id="book-category" aria-label="书页菜谱类别"><option value="all">全部类别</option>${Object.entries(cats).map(([key,name])=>`<option value="${key}" ${bookCategory===key?'selected':''}>${name}</option>`).join('')}</select></div><div id="book-reference-results">${bookReferenceItems()}</div>`;}
function matchingBookReferences(){return (D.bookReferences||[]).filter(r=>bookCategory==='all'||r.category===bookCategory).filter(r=>!bookSearch||r.name.includes(bookSearch)||recipe(r.recipeId)?.name.includes(bookSearch)||recipe(r.recipeId)?.ingredients.some(i=>food(i.foodId)?.name.includes(bookSearch)));}
function bookReferenceItems(){const matches=matchingBookReferences(),pages=Math.max(1,Math.ceil(matches.length/12));bookPage=Math.min(bookPage,pages-1);const start=bookPage*12;return `<div class="results-heading row"><span class="tiny">${matches.length}道 · 第${bookPage+1}/${pages}页</span></div><div class="reference-grid">${matches.slice(start,start+12).map(ref=>{const r=recipe(ref.recipeId);return `<article class="panel recipe-card stack"><div><h2>${h(ref.name)}</h2><span class="tiny">${h(cats[ref.category]||'参考')} · 书页${(ref.sourcePages||[]).join('、')}</span></div>${r?`<p class="tiny">${r.name!==ref.name?'做法：'+h(r.name)+' · ':''}动手${r.activeMin}分钟 · ${r.steps.length}步</p>${r.adapted?'<span class="tiny">家庭健康改写 · 可直接加入计划</span>':'<span class="tiny">已有原书配方 · 新手步骤</span>'}${btn('看做法',`data-recipe="${r.id}"`,'small')}`:btn('查看参考',`data-book-reference="${ref.id}"`,'small')}</article>`;}).join('')||'<p class="empty">没有找到，换个关键词试试。</p>'}</div><div class="pagination">${btn('上一页',`data-book-page="prev" ${bookPage===0?'disabled':''}`)}<span class="page-count">${bookPage+1} / ${pages}</span>${btn('下一页',`data-book-page="next" ${bookPage>=pages-1?'disabled':''}`)}</div>`;}
function refreshBookResults(){const node=document.getElementById('book-reference-results');if(node)node.innerHTML=bookReferenceItems();}
function bookReferenceSheet(id){const ref=(D.bookReferences||[]).find(r=>r.id===id);if(!ref)return;if(ref.recipeId&&recipe(ref.recipeId)){recipeSheet(ref.recipeId);return;}showSheet(ref.name,'<p>这条配方暂未载入，请刷新网页后重试。</p>');}
function recipeSheet(id){
 const r=recipe(id),per=standardItems(r),n=E.nutrition(per);modal={type:'recipe',id};
 const rows=items=>items.map(i=>`<div class="check-row"><span>${h(food(i.foodId).name)}</span><strong>${Math.round(i.g*10)/10}${food(i.foodId).unit}</strong></div>`).join('');
 const pantry=per.filter(i=>food(i.foodId).group==='condiment'&&i.foodId!=='water'),mainIngredients=per.filter(i=>food(i.foodId).group!=='condiment'||i.foodId==='water');
 const m=getMeal(),pids=(m.recipeIds.includes(id)?recipePeople(m,id):m.people),total=E.mergeItems(pids.map(pid=>mealBundle(m,pid).byRecipe.find(row=>row.recipeId===id)?.items||E.portion(r,findPerson(pid),m.size[pid]||1)));
 const sources=(r.sourceRefs||[]).filter(ref=>ref?.url&&/^https?:\/\//.test(ref.url));
 const sourceAmount=r.originalIngredients?.length?`<details class="recipe-extra"><summary>查看原书配方数量</summary>${r.originalIngredients.map(i=>`<div class="check-row"><span>${h(i.name)}</span><span>${h(i.quantityText||((i.amount??'')+(i.unit||'')))}</span></div>`).join('')}<p class="tiny">${h(typeof r.originalYield==='object'?r.originalYield.label:r.originalYield||'原方未注明人份')}</p></details>`:'';
 showSheet(r.name,`<div class="cook-guide">${recipeTags(r)}<div class="recipe-facts"><span><strong>${r.activeMin}分钟</strong>动手</span><span><strong>${r.totalMin>=120?Math.round(r.totalMin/6)/10+'小时':r.totalMin+'分钟'}</strong>全程参考</span><span><strong>${r.portions>1?'整批'+r.portions+(r.portionLabel||'份'):'1参考份'}</strong>${modeName(r.prep.mode)}</span></div>${r.uricAcidNote?`<p class="notice">尿酸关注：${h(r.uricAcidNote)}</p>`:''}${r.incomplete?recipeAssessment(r):r.frequency?`<p class="tiny">${h(r.frequency.label)}</p>`:''}<h3>先备料 · 每${h(r.portionLabel||'参考份')}</h3>${mainIngredients.length?rows(mainIngredients):'<p class="tiny">食材用量尚未填写。</p>'}${pantry.length?`<details class="recipe-extra pantry"><summary>调味用量</summary>${rows(pantry)}</details>`:''}${pids.length?`<details class="recipe-extra"><summary>按本餐选中的${pids.length}人备料</summary><p class="tiny">${pids.map(pid=>h(findPerson(pid).name)).join('、')}；已按各人份量设置计算。</p>${rows(total)}</details>`:''}${r.portions>1?`<details class="recipe-extra"><summary>整批${r.portions}${h(r.portionLabel||'份')}制作原料</summary>${rows(r.ingredients)}</details>`:''}<h3>照着做${r.portions>1?' · 按整批制作':''}</h3><p class="tiny">每完成一步可以勾一下。时间受锅具、火力和食材大小影响，熟透判断也要一起看。</p><div class="cook-steps">${r.steps.map((step,i)=>`<label class="cook-step"><input type="checkbox" aria-label="完成第${i+1}步"><span class="step-number">${i+1}</span><span class="step-text">${h(step)}</span></label>`).join('')}</div>${!r.incomplete?recipeAssessment(r):''}${r.noviceTips?.length?`<section class="novice-tips"><h3>第一次做，记住这几点</h3>${r.noviceTips.map(t=>`<p>${h(t)}</p>`).join('')}</section>`:''}${r.healthNotes?.length?`<details class="recipe-extra"><summary>健康搭配与备餐提示</summary>${r.healthNotes.map(t=>`<p class="tiny">${h(t)}</p>`).join('')}</details>`:''}<details class="recipe-extra"><summary>份量依据与参考来源</summary>${r.basisNote?`<p class="tiny">${h(r.basisNote)}</p>`:''}${r.sourcePages?.length?`<p class="tiny">菜单／原书来源页：${r.sourcePages.join('、')}。</p>`:''}${sources.map(ref=>`<p class="tiny">${h(ref.relation||'参考资料')}：<a href="${h(ref.url)}" target="_blank" rel="noreferrer">${h(ref.title)}</a></p>`).join('')}${!sources.length&&r.sourceIds?.length?r.sourceIds.map(sid=>{const ref=D.sources.find(x=>x.id===sid);return ref?`<p class="tiny">${ref.url?`<a href="${h(ref.url)}" target="_blank" rel="noreferrer">${h(ref.title||ref.label||ref.name||'资料来源')}</a>`:h(ref.title||ref.label||ref.name||'用户提供书页')}</p>`:'';}).join(''):''}</details>${sourceAmount}<details class="recipe-extra"><summary>配方营养估算</summary><p>能量${nutText(n,'kcal')} · 蛋白质${nutText(n,'protein')} · 碳水${nutText(n,'carbs')}</p><p class="tiny">参考原料逐项估算；未匹配成分保持未知，不把已知小计当完整营养。成品熟重${r.cookedG?'约'+r.cookedG+'g':'尚未实测'}。</p></details><label class="field">这道菜对我家<select class="select" id="recipe-skill" data-recipe-id="${r.id}"><option value="">还没标记</option><option value="familiar" ${recipeSkill(r.id)==='familiar'?'selected':''}>我会做</option><option value="try" ${recipeSkill(r.id)==='try'?'selected':''}>想尝试</option></select></label></div>`,r.retired?'<p class="tiny">历史菜谱保留条目。</p>':btn('加入这顿，按人数算量',`data-add-detail="${id}"`,'primary')+(r.id.startsWith('recipe-')?btn('补充自家菜',`data-edit-custom="${id}"`,'ghost'):btn('按我家做法改一份',`data-copy-custom="${id}"`,'ghost')));
}
function myPage(){const p=current(),assessment=E.profileAssessment(p);return `<div class="stack"><div class="page-head"><div><div class="tiny">${h(house().name)} · 每个人分开设置</div><h1>家人资料与喜好</h1></div>${btn('添加家人','data-add-person','primary')}</div><section class="panel stack"><h2>这家都有谁</h2>${people().map(m=>{const a=E.profileAssessment(m);return `<div class="check-row"><div><strong>${h(m.name)}</strong><p class="tiny">${m.age?m.age+'岁 · ':''}${a.ready?(a.energyKcal?'约'+Math.round(a.energyKcal)+'千卡/日参考':'个人目标已录'):'待完善：'+h(['child','elder','care'].includes(m.stage)?a.reason:(a.missingFields?.join('、')||a.reason))}</p></div>${btn('编辑资料',`data-edit-person="${m.id}"`,'small')}</div>`;}).join('')}</section><section class="panel stack" id="person-profile"><h2>编辑 ${h(p.name)} 的资料</h2><p class="tiny">资料直接影响该成员的参考份量；不会把所有家人统一乘一个系数。</p>${profileForm(p)}<div class="notice tiny">${h(assessment.reason||'')}${assessment.energyKcal?' · 参考能量约'+Math.round(assessment.energyKcal)+'千卡/日':''}${assessment.basis?.length?`<details><summary>看份量依据</summary>${assessment.basis.map(t=>`<p>${h(t)}</p>`).join('')}${(assessment.sourceRefs||[]).map(ref=>`<p><a href="${h(ref.url)}" target="_blank" rel="noreferrer">${h(ref.title)}</a></p>`).join('')}</details>`:''}</div></section>${preferenceUI.panel()}<section class="panel"><h2>这个家庭在哪里</h2><label class="field">城市<select class="select" id="city-picker"><option value="shanghai" ${house().city==='shanghai'?'selected':''}>上海</option><option value="guangzhou" ${house().city==='guangzhou'?'selected':''}>广州</option></select></label><p class="tiny">城市影响食材候选；米苋等有季节性的菜可以随时调整喜好。</p></section><section class="panel"><h2>喝水提醒计划</h2><div class="form-grid"><label class="field">开始<input class="input" type="time" id="water-start" value="${p.waterStart||'08:00'}"></label><label class="field">结束<input class="input" type="time" id="water-end" value="${p.waterEnd||'20:00'}"></label></div>${btn('保存提醒时段','data-save-water')}<p class="tiny">白天分散饮水。此版只保存时段，尚不会锁屏推送。</p></section><section class="panel"><h2>测试与备份</h2><div class="wrap">${btn('写测试反馈','data-feedback')}${btn('导出本机备份','data-export')}${btn('恢复备份','data-import')}${btn('来源与计算说明','data-sources','ghost')}</div><p class="tiny">数据在当前浏览器，不同设备暂不自动同步。</p><input type="file" id="import-file" accept="application/json" hidden></section></div>`;}
function profileForm(p){const activityMap={'以久坐为主':'sedentary','轻度活动':'light','中度活动':'moderate','较高活动':'active'},activity=activityMap[p.activity]||p.activity;return `<form id="profile-form"><div class="form-grid"><label class="field">名字<input class="input" name="name" value="${h(p.name)}" required maxlength="20"></label><label class="field">年龄<input class="input" name="age" type="number" min="1" max="120" value="${p.age??''}"></label><label class="field">身高 cm<input class="input" name="height" type="number" min="40" max="230" step=".1" value="${p.height??''}"></label><label class="field">体重 kg<input class="input" name="weight" type="number" min="3" max="300" step=".1" value="${p.weight??''}"></label><label class="field">性别<select class="select" name="sex" required>${[['unknown','请选择'],['female','女'],['male','男']].map(([k,v])=>`<option value="${k}" ${p.sex===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">阶段<select class="select" name="stage">${[['adult','一般成人'],['lactating','哺乳期'],['child','儿童'],['elder','老年人'],['care','需要照护']].map(([k,v])=>`<option value="${k}" ${p.stage===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">日常活动<select class="select" name="activity">${[['','请选择'],['sedentary','以久坐为主'],['light','轻度活动'],['moderate','中度活动'],['active','较高活动']].map(([k,v])=>`<option value="${k}" ${activity===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">是否有需单独执行的饮食医嘱<select class="select" name="specialDiet"><option value="unknown" ${p.specialDiet&&!p.specialDietState?'selected':''}>还不清楚</option><option value="no" ${!p.specialDiet?'selected':''}>没有特殊医嘱</option><option value="yes" ${p.specialDietState==='yes'?'selected':''}>有，按已有方案</option></select></label></div><div id="lactation-fields" ${p.stage==='lactating'?'':'hidden'} class="form-grid"><label class="field">宝宝月龄<input class="input" name="lactationMonths" type="number" min="0" max="48" step=".5" value="${p.lactationMonths??''}"></label><label class="field">喂养方式<select class="select" name="lactationMode"><option value="">请选择</option><option value="exclusive" ${p.lactationMode==='exclusive'?'selected':''}>纯母乳</option><option value="partial" ${p.lactationMode==='partial'?'selected':''}>混合喂养</option></select></label></div><div class="section-title">想重点关注（可多选）</div><div class="wrap">${[['glucose','血糖'],['pressure','血压'],['lipids','血脂'],['uric','尿酸']].map(([k,v])=>`<label class="chip"><input type="checkbox" name="focus" value="${k}" ${p.focus.includes(k)?'checked':''}>${v}</label>`).join('')}</div><label class="field">过敏、吞咽、限液或其他已有要求<textarea class="input" name="notes" maxlength="500">${h(p.notes||'')}</textarea></label><details><summary>已有个人目标 / 手动份量（儿童、照护或医嘱适用）</summary><p class="tiny">有专业人员给出的目标时录入；这里不自行给儿童减重或给照护长辈开饮食处方。</p><div class="form-grid"><label class="field">每日能量下限 千卡<input class="input" name="goalKcalMin" type="number" min="300" max="6000" value="${p.customGoals?.kcal?.min??''}"></label><label class="field">每日能量上限 千卡<input class="input" name="goalKcalMax" type="number" min="300" max="6000" value="${p.customGoals?.kcal?.max??''}"></label><label class="field">蛋白质参考 g/日<input class="input" name="goalProtein" type="number" min="1" max="250" value="${p.customGoals?.protein?.min??''}"></label><label class="field">钠限量 mg/日<input class="input" name="goalSodium" type="number" min="100" max="5000" value="${p.customGoals?.sodium?.max??''}"></label><label class="field">分餐方式<select class="select" name="portionMode"><option value="auto" ${p.portionMode!=='manual'?'selected':''}>按资料参考</option><option value="manual" ${p.portionMode==='manual'?'selected':''}>使用下方手动倍率</option></select></label></div><div class="form-grid">${['grain','protein','veg','fruit','dairy','nuts'].map(g=>`<label class="field">${groups[g]}倍率<input class="input" name="portion-${g}" type="number" min=".25" max="3" step=".05" value="${p.portionOverrides?.[g]??p.portions[g]??1}"></label>`).join('')}</div></details><button class="primary" type="submit">保存${h(p.name)}的资料</button></form>`;}
function showSheet(title,body,actions=''){
 if(!modalRoot.firstElementChild){sheetTrigger=document.activeElement;sheetScroll=window.scrollY;sheetBodyStyle=document.body.style.cssText;const gap=window.innerWidth-document.documentElement.clientWidth;document.body.style.position='fixed';document.body.style.top=-sheetScroll+'px';document.body.style.left='0';document.body.style.right='0';document.body.style.width='100%';document.body.style.overflow='hidden';if(gap>0)document.body.style.paddingRight=gap+'px';}
 modalRoot.innerHTML=`<div class="modal-backdrop" data-backdrop><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="sheet-head row"><h2 id="sheet-title">${h(title)}</h2>${btn('关闭','data-close','ghost')}</div><div class="sheet-body">${body}</div>${actions?`<div class="sheet-actions">${actions}</div>`:''}</section></div>`;
 modalRoot.querySelector('[data-close]')?.focus({preventScroll:true});
}
function closeSheet(){if(!modalRoot.firstElementChild){modal=null;changeIndex=null;return;}modalRoot.replaceChildren();document.body.style.cssText=sheetBodyStyle;window.scrollTo({top:sheetScroll,behavior:'instant'});if(sheetTrigger?.isConnected)sheetTrigger.focus({preventScroll:true});modal=null;changeIndex=null;sheetTrigger=null;}
function missingFoodPanel(items){const rows=items.map(i=>({f:food(i.foodId),keys:Object.keys(nutrients).filter(k=>food(i.foodId)?.nutrients?.[k]===null||food(i.foodId)?.nutrients?.[k]===undefined)})).filter(r=>r.keys.length);return rows.length?`<details class="recipe-extra"><summary>${rows.length}项食材有待核实成分</summary>${rows.map(r=>`<p class="tiny">${h(r.f.name)}：${r.keys.map(k=>nutrients[k][0]).join('、')}待补。</p>`).join('')}<p class="tiny">品牌食品可在“买菜 → 家里常备 → 详情 / 标签”补包装标签；普通食材由来源核对补充，不要求你逐项录。</p></details>`:'';}
function nutritionSheet(){const p=plannedPerson(),items=dayItems(p.id),n=E.nutrition(items),goals=E.goals(p);showSheet(p.name+' · 当天计划营养',`<div class="notice">按实际食材种类和配方克数累计；不同菜、不同做法不能等重量视为同营养。使用配方中所选食材或品牌标签估算；未匹配及烹饪损失部分仍待校准。</div>${missingFoodPanel(items)}<div class="nutrient-list">${Object.entries(nutrients).map(([key,[name]])=>{const g=goals[key],status=E.status(n.values[key],g,n.coverage[key]);return `<div class="nutrient"><div><strong>${name}</strong><p class="tiny">${g?h(g.source||'已确认参考'):'个人目标待确认'}${n.coverage[key]<1?' · 存在未匹配数据':''}</p></div><div style="text-align:right"><strong>${fmt(n.values[key],key)}</strong><p class="status-${status.kind}">${h(status.label)}</p></div></div>`;}).join('')}</div><p class="tiny">“达到推荐参考”不等于越多越好；蛋白超过RNI不自动判超量，钠限量不是需要凑满的目标。资料不全时不作医学达标判断。</p>`);}
function scoreSheet(){const p=plannedPerson(),m=getMeal(),result=mealScore(m,p.id);showSheet(labels[s.meal]+' · '+scoreLabel(result.score),`${healthReview(m,p)}${result.checks.map(c=>`<div class="check-row"><span>${c.passed?'✓':'○'} ${h(c.label)}</span><span>${c.passed?c.points:0}/${c.points}</span></div>`).join('')}<div class="notice">${h(result.note||'') }<br>这是本产品公开的搭配完整度检查，不是经过医学验证的健康风险评分。营养是否够量还要看全天营养、个人目标和数据完整度。</div>`);}
function totalSheet(){const m=getMeal(),totals=E.mergeItems(m.people.map(id=>itemsFor(m,id))).filter(i=>food(i.foodId).group!=='condiment');showSheet('这顿厨房总量',`${totals.map(i=>`<div class="check-row"><span>${h(food(i.foodId).name)}</span><strong>${Math.ceil(i.g)}${food(i.foodId).unit}</strong></div>`).join('')||'<p>这顿还没有选人或选菜。</p>'}<p class="tiny">净可食生重，含所有勾选的人；采购带骨、带壳食材另需换算。每个人的分量已在主页面逐行列出。</p>`);}
function chooseSheet(){const currentRecipe=changeIndex===null?null:recipe(getMeal().recipeIds[changeIndex]);modal={type:'choose'};showSheet(currentRecipe?'替换 '+currentRecipe.name:'加入这顿',`<input class="input" id="choose-search" value="${h(chooseQuery)}" placeholder="搜全部菜名或食材，例如：响油鳝丝、菠菜" aria-label="搜索加菜换菜"><div class="wrap">${[['all','全部'],...Object.entries(cats)].map(([key,text])=>btn(text,`data-choose-filter="${key}"`,'chip '+(chooseFilter===key?'selected':''))).join('')}</div><div id="choose-results">${chooseResults()}</div>`,btn('添加自家菜','data-build','primary'));}
function chooseResults(){const q=chooseQuery.trim(),rows=recipes().filter(r=>q?r.name.includes(q)||r.ingredients.some(i=>food(i.foodId)?.name.includes(q)):chooseFilter==='all'||r.category===chooseFilter);return `<p class="tiny">${q?'搜索全部分类 · ':''}${rows.length}道 · ${h(plannedPerson().name)}喜好优先</p><div class="recipe-list">${planner.rankRecipes(rows,[plannedPerson()]).map(r=>`<div class="recipe-item row"><div><strong>${h(r.name)}</strong><p class="tiny">${cats[r.category]} · 动手${r.activeMin}分钟 · ${modeName(r.prep.mode)}</p>${r.uricAcidNote?`<p class="tiny">尿酸关注：${h(r.uricAcidNote)}</p>`:''}</div>${btn(changeIndex===null?'加入':'替换成这道',`data-use="${r.id}"`)}</div>`).join('')||'<p class="empty">没有找到，可以直接添加自家菜。</p>'}</div>`;}
function useRecipe(id){const m=getMeal(),before=E.nutrition(dayItems());if(changeIndex===null)m.recipeIds.push(id);else m.recipeIds[changeIndex]=id;const after=E.nutrition(dayItems());const compared=E.compare(before,after);save();closeSheet();render();const delta=compared.protein===null?null:Math.round(compared.protein*10)/10;notify('计划已重算'+(delta===null?'':`，全天蛋白质${delta>=0?'+':''}${delta}g（配方估算）`)+'；实际记录保持原样。');}
function saveCustomRecipe(){const name=document.getElementById('custom-name').value.trim();if(!name){notify('先写一个菜名就可以。');return;}const portions=Number(document.getElementById('custom-portions').value);if(!Number.isFinite(portions)||portions<1||portions>20){notify('份数填写1到20之间。');return;}const ingredients=[...modalRoot.querySelectorAll('[data-custom-food]:checked')].map(el=>({foodId:el.dataset.customFood,g:Number(modalRoot.querySelector(`[data-custom-qty="${el.dataset.customFood}"]`).value)}));if(ingredients.some(i=>!Number.isFinite(i.g)||i.g<=0)){notify('勾选的食材请填写大于0的用量。');return;}const method=document.getElementById('custom-method').value.trim().slice(0,1500),category=planner.classify(name,ingredients);let id='recipe-'+s.house+'-'+Date.now();while(house().customRecipes.some(r=>r.id===id))id+='-1';const previous=modal?.editId?house().customRecipes.find(r=>r.id===modal.editId):null;const r={id,name,category,ingredients,portions,cookedG:null,activeMin:15,totalMin:20,steps:method?method.split(/\n+/).map(t=>t.trim()).filter(Boolean):['做法尚未填写；可以先保存菜名，之后再补。'],familyMethod:method,ingredientNote:document.getElementById('custom-note').value.trim().slice(0,400),incomplete:ingredients.length===0,prep:{mode:'fresh'},tags:['自家菜'],estimated:true,fixedMix:true,sizingGroup:category==='veg'?'veg':category==='grain'||category==='breakfast'?'grain':category==='snack'?'fruit':'protein',sourceRefs:[],basisNote:'用户自填配方；营养按已填写的食材用量估算，不凭菜名推断实际摄入。'};if(previous){previous.retired=true;for(const [key,m] of Object.entries(house().plans)){if(key.slice(0,10)<today())continue;m.recipeIds=m.recipeIds.map(rid=>rid===previous.id?id:rid);if(m.dishPeople[previous.id]){m.dishPeople[id]=m.dishPeople[previous.id];delete m.dishPeople[previous.id];}}}house().customRecipes.push(r);const m=getMeal();if(!m.recipeIds.includes(id))m.recipeIds.push(id);closeSheet();render();save();notify(r.incomplete?'菜名已保存；补用量后再估算营养和采购。':'自家菜已保存，分餐与采购已按份数更新。');}
function recipeAssessment(r){if(r.incomplete)return `<section class="notice tiny"><strong>已存菜名，营养和频次暂未评估</strong><p>${h(r.ingredientNote||'尚未填写食材用量。')}</p><p>这道菜暂不计入营养和采购，可点“补充自家菜”完善。</p></section>`;let lines=r.nutritionComment||[];if(!lines.length&&r.id.startsWith('recipe-')){const items=standardItems(r),foodGroups=new Set(items.map(i=>food(i.foodId)?.group));lines=[foodGroups.has('veg')?'配方有蔬菜，可在当天蔬菜安排中轮换。':'留意与当天其他菜搭配蔬菜。',foodGroups.has('protein')?'包含鱼肉蛋豆类，份量还要与当天其他蛋白食物合计。':'单道菜不必包含所有营养，按整餐搭配。'];const n=E.nutrition(items);if(n.unknown.length)lines.push('有食材成分未匹配，数值只显示已知部分。');}let frequency='';if(r.frequency){let count=0;const start=monday(s.day);for(let day=0;day<7;day++)for(const meal of Object.keys(labels)){const m=house().plans[addDay(start,day)+'-'+meal];if(m&&m.recipeIds.some(rid=>{const found=recipe(rid);return (rid===r.id||found?.name===r.name)&&recipePeople(m,rid).includes(s.planPerson);}))count++;}frequency=`<p><strong>${h(r.frequency.label)}</strong></p><p class="tiny">${h(r.frequency.reason)}</p><p class="tiny">${h(plannedPerson().name)}本周已保存餐单中安排${count}次。${h(r.frequency.scope||'家庭排餐参考，并非按单菜规定的医疗处方。')}</p>`;}else if(r.id.startsWith('recipe-'))frequency='<p class="tiny">频次按实际用油、用盐及全周同类食物合计；目前不给自填菜名设定固定医学次数。</p>';return lines.length||frequency?`<section class="recipe-assessment"><h3>营养与安排频次</h3>${lines.map(t=>`<p class="tiny">${h(t)}</p>`).join('')}${frequency}</section>`:'';}
function brandPicker(r){
 if(!r)return '';
 const pairs=[[/牛奶|^milk$/,/牛奶/],[/燕麦|oat/,/麦片|燕麦/],[/面包|吐司|bread|toast/,/面包/],[/面条|noodle/,/面条/],[/^oil$|食用油|橄榄油|菜籽油|牛油果油/,/牛油果油|橄榄油|菜籽油/]];
 const rows=r.ingredients.map(i=>{const f=food(i.foodId),pair=pairs.find(([re])=>re.test(i.foodId+' '+f.name));if(!pair)return '';const options=(house().pantry||[]).filter(row=>row.status!=='out'&&pair[1].test(row.name)&&food(row.foodId)?.unit===f.unit);return options.length?`<label class="field">${h(f.name)}换为家里品牌<select class="select" data-brand-for="${i.foodId}"><option value="${i.foodId}">保留配方参考食材</option>${options.map(row=>`<option value="${row.foodId}">${h(row.name)}${food(row.foodId).verified?'':' · 标签待核对'}</option>`).join('')}</select></label>`:'';}).filter(Boolean);
 return rows.length?`<details><summary>换成家里常备品牌</summary>${rows.join('')}<p class="tiny">保留原配方相同单位用量，品牌标签不全时营养显示未知。预制牛肉/鸡排的生熟和调味与鲜肉不同，不自动等量替换。</p></details>`:'';
}

function builderSheet(id=null){const r=id?recipe(id):null;modal={type:'builder',editId:r&&house().customRecipes.some(x=>x.id===id)?id:null};const choices=[...new Set(baseFoodIds.concat(Object.keys(house().customFoods)))],selected=new Map((r?.ingredients||[]).map(i=>[i.foodId,i.g]));const method=r?.familyMethod||(r&&!r.incomplete?r.steps.join('\n'):'');showSheet(r?'按我家做法调整':'添加自家菜',`<label class="field">菜名<input class="input" id="custom-name" value="${h(r?.name||'')}" placeholder="例如：爷爷的芹菜豆干牛肉丝" maxlength="50"></label><div class="form-grid"><input type="hidden" id="custom-category" value="${r?.category||'protein'}"><div class="tiny" id="custom-category-label">${r?'自动归类：'+cats[r.category]:'输入菜名后自动归类，无需选择。'}</div><label class="field">这些原料做几份<input class="input" id="custom-portions" type="number" min="1" max="20" step="1" value="${r?.portions||1}"></label></div>${brandPicker(r)}<div id="known-recipe-hint"></div><label class="field">食材随手写（可不填）<input class="input" id="custom-note" value="${h(r?.ingredientNote||'')}" maxlength="400" placeholder="例如：芹菜、豆干、少量牛肉"></label><label class="field">我家的做法（可不填）<textarea class="input" id="custom-method" rows="3" maxlength="1500" placeholder="可以按一行一步写，或先只保存菜名">${h(method)}</textarea></label><details ${selected.size?'open':''}><summary>补食材用量，估算营养和采购</summary><p class="tiny">填写整锅用量，按上面的份数分餐。未填写时只保存菜名，不虚报营养。</p><input class="input" id="food-search" placeholder="输入食材筛选，如牛肉、豆干"><div id="ingredient-options">${choices.map((fid,index)=>`<div class="ingredient-row" data-food-name="${h(food(fid).name)}" data-default-hidden="${!selected.has(fid)&&index>=18}" ${!selected.has(fid)&&index>=18?'hidden':''}><label><input type="checkbox" data-custom-food="${fid}" ${selected.has(fid)?'checked':''}>${h(food(fid).name)}</label><input class="input" type="number" min="0.1" max="5000" step="0.1" data-custom-qty="${fid}" value="${selected.get(fid)||100}" ${selected.has(fid)?'':'disabled'} aria-label="${h(food(fid).name)}整锅用量"><span>${food(fid).unit}</span></div>`).join('')}</div><details><summary>没有找到？新增食材</summary><input class="input" id="new-food-name" placeholder="食材名称" maxlength="30"><select class="select" id="new-food-group">${Object.entries(groups).map(([key,text])=>`<option value="${key}">${text}</option>`).join('')}</select>${btn('加入候选','data-new-food')}<p class="tiny">新增食材尚无成分时保留未知。</p></details></details>`,btn('保存自家菜并用于这顿','data-save-custom','primary'));}
function dishPeopleSheet(id){const m=getMeal();modal={type:'dishPeople',id};showSheet(recipe(id).name+' · 谁吃',`${m.people.map(pid=>`<label class="check-row"><span>${h(findPerson(pid).name)}</span><input type="checkbox" data-dish-check="${pid}" ${recipePeople(m,id).includes(pid)?'checked':''}></label>`).join('')||'<p>先在主页面选择这顿用餐的人。</p>'}`,btn('保存这道的就餐人','data-save-dish-people','primary'));}
function migratePlanningDefaults(){
 if(s.planningVersion===planner.VERSION)return;
 const oldPick=(category,index)=>{const list=D.recipes.filter(r=>r.category===category&&r.defaultEligible!==false&&!r.id.includes('out'));return list[index%list.length]?.id;};
 let changed=0;
 for(const [hid,space] of Object.entries(s.houses))for(const [key,m] of Object.entries(space.plans)){
  if(key.slice(0,10)<today())continue;
  const kind=key.slice(11),i=(new Date(key.slice(0,10)+'T12:00:00Z').getUTCDay()+6)%7;
  const old=kind==='breakfast'?[oldPick('breakfast',i%3)]:kind==='snack'?[oldPick('snack',i%3)]:[oldPick('grain',i%2),oldPick('protein',i%5),oldPick('veg',i%5)];
  if(JSON.stringify(m.recipeIds)!==JSON.stringify(old.filter(Boolean))||Object.keys(m.dishPeople||{}).length||Object.keys(m.size||{}).length)continue;
  const next=planner.build(kind,i,{houseId:hid,members:space.members,recipes:D.recipes.concat(space.customRecipes.filter(r=>!r.retired)),city:space.city});
  m.recipeIds=next.recipeIds;m.origin=planner.VERSION;m.prepNote=next.prepNote;changed++;
 }
 s.planningVersion=planner.VERSION;
 if(changed)setTimeout(()=>notify('未调整的旧参考菜单已改为午餐备餐、晚餐家常；自选菜和过去记录保留。'),100);
}
function weekNutritionSheet(){
 const p=plannedPerson(),a=E.profileAssessment(p),goals=E.goals(p),start=monday(s.day),keys=['kcal','protein','fiber','sodium','saturatedFat'];
 const total=planner.referenceAmounts({ingredients:E.mergeItems(Array.from({length:7},(_,i)=>dayItems(p.id,addDay(start,i)))),portions:1});
 const rows=Array.from({length:7},(_,i)=>{const d=addDay(start,i),n=E.nutrition(dayItems(p.id,d)),mealCount=['breakfast','lunch','dinner'].filter(type=>itemsFor(getMeal(d,type),p.id).length).length;return `<section class="panel stack"><div class="row"><strong>${dateLabel(d)}</strong><span class="tiny">${mealCount}/3餐在家计划</span></div>${keys.map(k=>{const status=E.status(n.values[k],goals[k],n.coverage[k]);return `<div class="row"><span>${nutrients[k][0]}</span><span>${nutText(n,k)} · <small class="status-${status.kind}">${mealCount<3&&status.kind!=='high'?'只计计划内餐食':h(status.label)}</small></span></div>`;}).join('')}</section>`;});
 showSheet(p.name+' · 一周营养预估',`<p class="notice">${a.ready?'按该成员资料与配方计算，仍是参考估算。':'个人目标待完善：'+h(a.reason)} 未安排的校餐、外食和未知品牌成分不算成零；配方估算不等于实际吸收。</p><p class="tiny">本周本人计划内累计：畜禽肉约${Math.round(total.meatG)}g，水产约${Math.round(total.fishG)}g。${p.age>=18&&p.stage!=='care'?'健康成人全周每类300—500g是通用膳食参考，不是医学安全上限；少于3餐在家时还需计入外食。':'儿童及照护者需适用的个人参考，不能套成人目标。'}${total.meatG>500||total.fishG>500?'当前累计较多，建议回看份量与频次。':''}</p><div class="stack">${rows.join('')}</div><details><summary>参考目标与依据</summary>${keys.map(k=>`<p class="tiny">${nutrients[k][0]}：${goals[k]?h(goals[k].source):'个人目标未确认'}</p>`).join('')}</details>`);
}
let proposedWeek=null;
function replanSheet(){
 const start=monday(s.day);
 proposedWeek=planner.buildWeek({houseId:s.house,members:people(),recipes:recipes(),city:house().city,startDay:start,existingPlans:house().plans});
 const plans=proposedWeek.plans;
 showSheet('先看这一周的新安排',`<p class="notice">保存后更新今天及以后的本周餐单，保留就餐人，份量按最新资料重新计算；过去餐单与实吃记录不变。</p><div class="stack">${Array.from({length:7},(_,i)=>{const day=addDay(start,i);return `<section class="panel"><h3>${dateLabel(day)}${day<today()?' · 过去日期保留':''}</h3>${['breakfast','lunch','dinner','snack'].map(kind=>`<p class="tiny"><strong>${labels[kind]}</strong> ${(plans[day+'-'+kind]?.recipeIds||[]).map(id=>h(recipe(id)?.name||'')).join('、')}</p>`).join('')}</section>`;}).join('')}</div>${(proposedWeek.notes||[]).map(t=>`<p class="tiny">${h(t)}</p>`).join('')}`,btn('保存这周的新安排','data-apply-week','primary'));
}
function applyWeek(){
 if(!proposedWeek)return;
 for(const [key,m] of Object.entries(proposedWeek.plans)){
  if(key.slice(0,10)<today())continue;
  const old=house().plans[key];
  if(old)m.people=old.people.slice();
  m.dishPeople={};m.size={};house().plans[key]=m;
 }
 proposedWeek=null;closeSheet();s.period='week';render();save();notify('已按喜好和备餐条件重排未来餐单；过去记录保留。');
}

function batchSummary(){const start=monday(s.day),counts={};for(let i=0;i<7;i++)for(const meal of Object.keys(labels)){const m=getMeal(addDay(start,i),meal);for(const id of m.recipeIds){const r=recipe(id);if(r?.prep.mode!=='fresh')counts[id]=(counts[id]||0)+recipePeople(m,id).length;}}showSheet('本周备菜汇总',`${Object.entries(counts).map(([id,count])=>`<div class="check-row"><div><strong>${h(recipe(id).name)}</strong><p class="tiny">${modeName(recipe(id).prep.mode)}</p></div><span>${count}份参考分装</span></div>`).join('')||'<p>当前菜单的冷冻组件还不多。可以先在备餐页选择主食、蛋白和蔬菜包，再用于几顿。</p>'}<p class="tiny">这里的份数按参与人数汇总；具体净用量请看采购页。焯水原料不等于即食菜；贴日期、分装并按原料状态烹调或彻底复热。</p>`);}
function feedbackSheet(){modal={type:'feedback'};showSheet('把测试意见带回这个聊天',`<label class="field">哪一步不方便，期望怎样<textarea class="input" id="feedback-text" placeholder="例如：广州家选两位长辈后，采购量想按三天合并"></textarea></label><p class="tiny">反馈先保存在本机，复制后发给我；不会自动发送给其他人。</p>`,btn('保存并复制反馈','data-save-feedback','primary'));}
async function copy(text){try{await navigator.clipboard.writeText(text);notify('已复制，可以粘贴发给我。');}catch{showSheet('复制这段文字',`<textarea class="input" rows="8" readonly>${h(text)}</textarea>`);}}
function render(){const oldPlan=document.querySelector('.plan-layout'),oldPlanKey=oldPlan?.dataset.planKey,openPeople=[...document.querySelectorAll('.person-portion[open]')].map(el=>el.dataset.portionPerson);const draft=document.getElementById('rough-text');if(draft)roughDrafts[draft.dataset.draftKey]=draft.value;syncCustomFoods();pantryUI.ensure();document.body.dataset.view=s.view;document.getElementById('house-picker').value=s.house;main.innerHTML=s.view==='plan'?planning():s.view==='shop'?shopping():s.view==='library'?library():myPage();if(document.querySelector('.plan-layout')?.dataset.planKey===oldPlanKey)document.querySelectorAll('.person-portion').forEach(el=>el.open=openPeople.includes(el.dataset.portionPerson));if(['shop'].includes(s.view)&&s.shopTab!=='pantry'){const content=main.firstElementChild,panels=[...content.children].filter(el=>el.tagName==='SECTION'),grid=document.createElement('div');grid.className=s.view==='shop'?'shopping-grid':'settings-grid';if(panels.length){panels[0].before(grid);panels.forEach(el=>grid.append(el));}}document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===s.view);b.setAttribute('aria-current',b.dataset.nav===s.view?'page':'false');});}
document.addEventListener('click',async event=>{if(event.target.hasAttribute('data-backdrop')){closeSheet();return;}const b=event.target.closest('button');if(!b)return;if(pantryUI.click(b)||preferenceUI.click(b))return;
 if(b.dataset.shopTab){s.shopTab=b.dataset.shopTab;render();}
 else if(b.hasAttribute('data-preference-panel'))showSheet('个人喜好与优先顺序',preferenceUI.panel());
 else if(b.hasAttribute('data-open-profiles')){s.view='me';s.person=s.planPerson;render();}
 else if(b.dataset.editPerson){s.person=b.dataset.editPerson;s.planPerson=b.dataset.editPerson;s.view='me';render();document.getElementById('person-profile')?.scrollIntoView({block:'start'});}
 else if(b.hasAttribute('data-add-person'))showSheet('添加家人',`<label class="field">称呼<input class="input" id="member-name" maxlength="20" placeholder="例如：妈妈、小姨"></label>`,btn('添加并补资料','data-save-person','primary'));
 else if(b.hasAttribute('data-save-person')){const name=document.getElementById('member-name').value.trim();if(!name){notify('先填写称呼');return;}const p=member('person-'+Date.now(),name);people().push(p);s.person=p.id;s.planPerson=p.id;closeSheet();s.view='me';render();}
 else if(b.hasAttribute('data-week-nutrition'))weekNutritionSheet();
 else if(b.hasAttribute('data-replan-week'))replanSheet();
 else if(b.hasAttribute('data-apply-week'))applyWeek();
 else if(b.dataset.knownRecipe)builderSheet(b.dataset.knownRecipe);
 else if(b.dataset.bookReference)bookReferenceSheet(b.dataset.bookReference);
 else if(b.hasAttribute('data-book-more')){bookPage++;refreshBookResults();}
 else if(b.dataset.completeBook){const ref=(D.bookReferences||[]).find(r=>r.id===b.dataset.completeBook);if(ref){changeIndex=null;builderSheet();document.getElementById('custom-name').value=ref.name;document.getElementById('custom-category').value=ref.category;notify('按你家做法补齐原料和用量，再保存为可排餐菜谱。');}}
 else if(b.dataset.recipePage){recipePage=Math.max(0,recipePage+(b.dataset.recipePage==='next'?1:-1));refreshRecipeResults();scrollCatalogResults();}
 else if(b.dataset.bookPage){bookPage=Math.max(0,bookPage+(b.dataset.bookPage==='next'?1:-1));refreshBookResults();scrollCatalogResults();}
 else if(b.dataset.openMeal){s.day=b.dataset.openMeal;s.meal=b.dataset.mealType;s.period='day';s.view='plan';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.dataset.nav){s.view=b.dataset.nav;closeSheet();render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.dataset.period){s.period=b.dataset.period;render();}
 else if(b.dataset.meal){s.meal=b.dataset.meal;render();}
 else if(b.dataset.day){s.day=b.dataset.day;s.period='day';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.hasAttribute('data-only')){getMeal().people=[current().id];render();}
 else if(b.hasAttribute('data-all')){getMeal().people=people().map(p=>p.id);render();}
 else if(b.dataset.person){const m=getMeal(),id=b.dataset.person;m.people=m.people.includes(id)?m.people.filter(p=>p!==id):m.people.concat(id);render();}
 else if(b.hasAttribute('data-score')||b.hasAttribute('data-summary-score'))scoreSheet();
 else if(b.hasAttribute('data-nutrition'))nutritionSheet();
 else if(b.hasAttribute('data-prep-total'))totalSheet();
 else if(b.hasAttribute('data-open-prep')){s.view='library';s.filter='prep';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.hasAttribute('data-choose')){changeIndex=null;chooseQuery='';chooseFilter=s.meal==='breakfast'?'breakfast':s.meal==='snack'?'snack':'protein';chooseSheet();}
 else if(b.dataset.change!==undefined){chooseQuery='';changeIndex=Number(b.dataset.change);chooseFilter=recipe(getMeal().recipeIds[changeIndex]).category;chooseSheet();}
 else if(b.dataset.chooseFilter){chooseFilter=b.dataset.chooseFilter;chooseSheet();}
 else if(b.dataset.use)useRecipe(b.dataset.use);
 else if(b.dataset.addDetail){const id=b.dataset.addDetail;changeIndex=null;useRecipe(id);}
 else if(b.dataset.packUse){changeIndex=null;useRecipe(b.dataset.packUse);s.view='plan';render();window.scrollTo({top:0,behavior:'instant'});}
 else if(b.dataset.removeDish!==undefined){getMeal().recipeIds.splice(Number(b.dataset.removeDish),1);render();notify('这道已移出计划，分量、营养与采购已重算。');}
 else if(b.dataset.recipe)recipeSheet(b.dataset.recipe);
 else if(b.dataset.dishPeople)dishPeopleSheet(b.dataset.dishPeople);
 else if(b.hasAttribute('data-save-dish-people')){getMeal().dishPeople[modal.id]=[...modalRoot.querySelectorAll('[data-dish-check]:checked')].map(i=>i.dataset.dishCheck);closeSheet();render();}
 else if(b.hasAttribute('data-close'))closeSheet();
 else if(b.dataset.editCustom)builderSheet(b.dataset.editCustom);
 else if(b.dataset.copyCustom)builderSheet(b.dataset.copyCustom);
 else if(b.hasAttribute('data-build'))builderSheet();
 else if(b.hasAttribute('data-new-food')){const name=document.getElementById('new-food-name').value.trim();if(name){const id='custom-'+s.house+'-'+Date.now();house().customFoods[id]={id,name,unit:'g',group:document.getElementById('new-food-group').value,nutrients:Object.fromEntries(Object.keys(nutrients).map(k=>[k,null])),verified:false,source:{label:'家庭新增，成分待匹配',url:'',id,state:'可食生重'}};syncCustomFoods();const row=document.createElement('div');row.className='ingredient-row';row.dataset.foodName=name;row.innerHTML=`<label><input type="checkbox" data-custom-food="${id}" checked>${h(name)}</label><input class="input" type="number" min="1" max="3000" step="5" data-custom-qty="${id}" value="100" aria-label="${h(name)}用量"><span>g</span>`;document.getElementById('ingredient-options').append(row);notify('食材已加到候选，营养保持未知。');}}
 else if(b.hasAttribute('data-save-custom'))saveCustomRecipe();
 else if(b.hasAttribute('data-rough-save')){const text=document.getElementById('rough-text').value.trim().slice(0,400);if(!text){notify('写一句吃了什么就可以。');return;}const draft=document.getElementById('rough-text');delete roughDrafts[draft.dataset.draftKey];draft.value='';const estimate=E.roughLog(text);s.records.push({id:'record-'+Date.now(),house:s.house,owner:s.person,actor:s.person,day:s.day,text,period:estimate.period||s.meal,portionText:estimate.portionText||'粗略记录',kcal:estimate.kcal||null,note:estimate.note});render();notify('已粗记，不影响备餐计划。');}
 else if(b.hasAttribute('data-log-plan')){const n=E.nutrition(itemsFor(getMeal(),s.person));const key='plan-'+s.house+'-'+s.person+'-'+s.day+'-'+s.meal;const entry={id:key,house:s.house,owner:s.person,actor:s.person,day:s.day,text:getMeal().recipeIds.filter(id=>recipePeople(getMeal(),id).includes(s.person)).map(id=>recipe(id).name).join('、')||'这顿未安排本人',period:s.meal,portionText:'按本次计划份量确认',kcal:n.coverage.kcal===1?[n.values.kcal*.85,n.values.kcal*1.15]:null};s.records=s.records.filter(x=>x.id!==key).concat(entry);render();notify('已确认这顿；以后改菜单不会自动改实吃记录。');}
 else if(b.dataset.recordRemove){s.records=s.records.filter(x=>!(x.id===b.dataset.recordRemove&&x.house===s.house&&x.owner===s.person));render();}
 else if(b.hasAttribute('data-water-add')){s.water.push({house:s.house,owner:s.person,day:s.day});render();notify('已记一杯水。');}
 else if(b.dataset.filter){s.filter=b.dataset.filter;recipePage=0;recipeQuery='';bookPage=0;render();scrollCatalogResults();}
 else if(b.hasAttribute('data-batch-summary'))batchSummary();
 else if(b.dataset.shopRange){s.shopRange=b.dataset.shopRange;render();}
 else if(b.dataset.have){s.bought[b.dataset.have]=Number(b.dataset.grams);render();}
 else if(b.hasAttribute('data-copy-shop'))copy(allShopping().map(i=>`${food(i.foodId).name} ${Math.ceil(i.g)}${food(i.foodId).unit}`).join('\n'));
 else if(b.hasAttribute('data-fill-week')){const start=monday(s.day);for(let i=0;i<7;i++)for(const meal of Object.keys(labels)){const key=addDay(start,i)+'-'+meal;if(!house().plans[key])house().plans[key]=newMeal(meal,i);}render();notify('空餐已用参考菜单补齐，没有覆盖已修改的餐单。');}
 else if(b.hasAttribute('data-save-water')){current().waterStart=document.getElementById('water-start').value;current().waterEnd=document.getElementById('water-end').value;notify('时段已保存；此版手机通知尚未启用。');}
 else if(b.hasAttribute('data-notification-preview'))showSheet('喝水提醒 · 样式预览','<p>现在方便喝几口水吗？</p><p class="subtle">稍后提醒 / 今天暂停</p><div class="notice">这只是提醒文案预览，没有申请或启用手机通知。错过的提醒不累计成睡前催喝。</div>');
 else if(b.hasAttribute('data-feedback'))feedbackSheet();
 else if(b.hasAttribute('data-save-feedback')){const text=document.getElementById('feedback-text').value.trim();if(text){const message=`好好吃饭测试反馈\n页面：${s.view}\n家庭：${house().name}（${house().city==='guangzhou'?'广州':'上海'}）\n${text}`;s.feedback.push({text:message,time:new Date().toISOString()});closeSheet();await copy(message);}}
 else if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='好好吃饭-本机备份-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 else if(b.hasAttribute('data-import'))document.getElementById('import-file').click();
 else if(b.hasAttribute('data-sources'))showSheet('来源与计算说明',`<p>营养＝每100g成分 × 原料可食生重，逐项相加。熟重、品牌、烹调留存未校准的部分保持估算。</p><p>食物重不等于营养素重：鸡肉与豆腐、生菜与西兰花需按各自条目重算，不能按同克数互换。</p><p>未知值不填零；RNI/AI不是安全上限，钠限量不是需吃满的目标。</p>${D.sources.map(source=>source.url?`<p><a target="_blank" rel="noreferrer" href="${h(source.url)}">${h(source.title||source.label||source.name||'来源')}</a></p>`:`<p>${h(source.title||source.label||source.name||'用户书页参考')}</p>`).join('')}<p class="tiny">测试版不提供诊断、用药或吞咽治疗建议；记录覆盖不足时不判断长期营养缺乏。</p>`);
 save();
});
document.addEventListener('change',event=>{const el=event.target;if(pantryUI.change(el)||preferenceUI.change(el))return;
 if(el.id==='house-picker'){s.house=el.value;s.person=people()[0].id;s.planPerson=s.person;closeSheet();render();}
 else if(el.id==='day-picker'){if(el.value)s.day=el.value;render();}
 else if(el.name==='stage'){document.getElementById('lactation-fields').hidden=el.value!=='lactating';}
 else if(el.id==='library-sort'){s.librarySort=el.value;recipePage=0;refreshRecipeResults();}
 else if(el.id==='library-person'){s.planPerson=el.value;recipePage=0;render();}
 else if(el.id==='plan-person'){s.planPerson=el.value;render();}
 else if(el.id==='record-person'){s.person=el.value;render();}
 else if(el.dataset.size){getMeal().size[el.dataset.size]=Number(el.value);render();}
 else if(el.dataset.buy){s.bought[el.dataset.buy]=el.checked?Number(el.dataset.grams):0;render();}
 else if(el.id==='city-picker'){house().city=el.value;render();}
 else if(el.dataset.brandFor){const old=el.dataset.brandFor,target=el.value,a=modalRoot.querySelector(`[data-custom-food="${old}"]`),av=modalRoot.querySelector(`[data-custom-qty="${old}"]`),b=modalRoot.querySelector(`[data-custom-food="${target}"]`),bv=modalRoot.querySelector(`[data-custom-qty="${target}"]`);if(a&&av&&b&&bv){const qty=av.value;a.checked=false;av.disabled=true;b.checked=true;bv.disabled=false;bv.value=qty;b.closest(".ingredient-row").hidden=false;notify("已换为所选品牌；营养按该食品标签数据重算。");}}
 else if(el.dataset.customFood){modalRoot.querySelector(`[data-custom-qty="${el.dataset.customFood}"]`).disabled=!el.checked;}
 else if(el.id==='skill-filter'){skillFilter=el.value;recipePage=0;refreshRecipeResults();}
 else if(el.id==='book-category'){bookCategory=el.value;bookPage=0;refreshBookResults();}
 else if(el.id==='recipe-skill'){const id=el.dataset.recipeId;house().recipeSkills=house().recipeSkills||{};if(el.value)house().recipeSkills[id]=el.value;else delete house().recipeSkills[id];if(s.view==='library')render();notify('这道菜的熟悉程度已保存在本家庭。');}
 else if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>2000000){notify('备份文件太大，未导入。');return;}file.text().then(text=>{
  let previousState,previousRaw,previousFoods,changed=false;
  try{const candidate=validateBackup(parseBackup(text));if(candidate.filter==='book')candidate.filter='all';previousRaw=localStorage.getItem(STORE);previousState=s;previousFoods={...D.foods};s=candidate;changed=true;applyCatalogRevision();render();localStorage.setItem(STORE,JSON.stringify(s));notify('本机备份已恢复。');}
  catch{if(changed){s=previousState;for(const id of Object.keys(D.foods))if(!Object.hasOwn(previousFoods,id))delete D.foods[id];Object.assign(D.foods,previousFoods);try{if(localStorage.getItem(STORE)!==previousRaw){if(previousRaw===null)localStorage.removeItem(STORE);else localStorage.setItem(STORE,previousRaw);}}catch{}try{render();}catch{}}notify('导入未完成，现有资料保留。');}
 }).catch(()=>notify('备份读取失败，现有资料保留。'));return;}
 save();
});
document.addEventListener('input',event=>{if(pantryUI.input(event.target))return;if(event.target.id==='choose-search'){chooseQuery=event.target.value;document.getElementById('choose-results').innerHTML=chooseResults();}else if(event.target.id==='custom-name'){const name=event.target.value.trim(),cat=planner.classify(name);document.getElementById('custom-category-label').textContent='自动归类：'+cats[cat];const found=recipes().find(r=>r.name===name);document.getElementById('known-recipe-hint').innerHTML=found?btn('已有这道菜，带入标准做法和用量',`data-known-recipe="${found.id}"`,'ghost small'):'';}else if(event.target.id==='food-search'){const query=event.target.value.trim();modalRoot.querySelectorAll('[data-food-name]').forEach(row=>row.hidden=query?!row.dataset.foodName.includes(query):(row.dataset.defaultHidden==='true'&&!row.querySelector('input[type=checkbox]')?.checked));}else if(event.target.id==='book-search'){bookSearch=event.target.value.trim();bookPage=0;refreshBookResults();}else if(event.target.id==='recipe-search'){recipeQuery=event.target.value.trim();recipePage=0;refreshRecipeResults();}else if(event.target.id==='rough-text'){roughDrafts[event.target.dataset.draftKey]=event.target.value;}});
document.addEventListener('submit',event=>{if(event.target.id!=='profile-form')return;event.preventDefault();const f=new FormData(event.target),p=current(),get=k=>f.get(k)===''?null:Number(f.get(k)),min=get('goalKcalMin'),max=get('goalKcalMax');if((min===null)!==(max===null)||min!==null&&min>max){notify('个人能量范围请同时填上下限，并检查顺序。');return;}const goals={};if(min!==null)goals.kcal={type:'range',min,max,source:'用户录入的已有个人能量目标'};if(get('goalProtein')!==null)goals.protein={type:'minimum',min:get('goalProtein'),source:'用户录入的个人蛋白质参考'};if(get('goalSodium')!==null)goals.sodium={type:'maximum',max:get('goalSodium'),source:'用户录入的个人钠限量'};Object.assign(p,{name:String(f.get('name')).trim()||p.name,age:get('age'),height:get('height'),weight:get('weight'),focus:f.getAll('focus'),sex:f.get('sex'),stage:f.get('stage'),activity:f.get('activity'),specialDiet:f.get('specialDiet')!=='no',specialDietState:f.get('specialDiet'),notes:String(f.get('notes')||'').slice(0,500),lactationMonths:get('lactationMonths'),lactationMode:f.get('lactationMode'),portionMode:f.get('portionMode'),customGoals:goals,profileConfirmed:true});if(p.portionMode==='manual')p.portionOverrides=Object.fromEntries(['grain','protein','veg','fruit','dairy','nuts'].map(g=>[g,get('portion-'+g)||1]));else delete p.portionOverrides;save();render();notify(E.profileAssessment(p).ready?'该成员的资料和参考份量已更新；一周营养已重算。':'资料已保存，尚缺的部分会在成员旁提示。');});
document.addEventListener('keydown',e=>{if(!modalRoot.childElementCount)return;if(e.key==='Escape'){e.preventDefault();closeSheet();}else if(e.key==='Tab'){const nodes=[...modalRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary,[tabindex="0"]')].filter(node=>node.getClientRects().length);if(!nodes.length){e.preventDefault();modalRoot.querySelector('.sheet').focus();return;}const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||!modalRoot.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!modalRoot.contains(document.activeElement))){e.preventDefault();first.focus();}}});
for(const [id,space] of Object.entries(s.houses))if(id!=="home"&&!Array.isArray(space.pantry))space.pantry=[];syncCustomFoods();migratePlanningDefaults();if(s.filter==='book')s.filter='all';applyCatalogRevision();render();save();
})();
